const steps = 100;
let size;
let fps;
let s;

function setup() {
	createCanvas(windowWidth, windowHeight)
	size = windowWidth/steps;
	fps=30;
	frameRate(fps);
	s=0
}
function draw() {
	background(0, 10);
	push()
	translate(windowWidth/2, windowHeight/2);
	for (let i=0;i<steps;i++){
		stroke(255);
		if (floor(frameCount % fps) === 0) {
			strokeWeight(10);
		} else {
			strokeWeight(3);
		}
		point(-windowWidth / 2 + i* size, 0 + random(-windowHeight/2,windowHeight/2));
	}
	pop();
	strokeWeight(1);
	fill(255);
	circle(s*size, windowHeight/2 + sin(frameCount)*10, 20+sin(frameCount)*10);
	fill(0);
	circle(s*size, windowHeight/2 + cos(frameCount)*10, 20+sin(frameCount)*10);
	s++;
	if (s === steps) {
		s=0;
	}
}

let arrayLen = 100;
let arrayItems = [];

function setup() {
	frameRate(30);
	createCanvas(windowWidth, windowHeight)
	for(i=0;i<arrayLen;i++) {
		arrayItems.push(new FancyObject(
			random(300, 900),
			random(30, 120)));
	}
}

function draw() {
	background(0,5);
	arrayItems.forEach((item)=>
	{
		if (frameCount > item.delay) {
			item.update();
			item.draw();
		}
	});
}

class FancyObject {
	constructor(age, delay) {
		this.reset(age, delay);
	}

	reset(age, delay) {
		this.maxAge = age;
		this.age = 0;
		this.delay = delay;
		this.x = random(0, windowWidth);
		this.y = random(0, windowHeight);
		this.speed = random(1,5);
		this.color = color(random(255), random(0), random(255));
	}

	update() {
		this.r = map(this.age, 0, this.maxAge, 10, 250);
		this.alpha = map(this.age, 0, this.maxAge, 250, 0);
		this.color = color(red(this.color)*abs(sin(this.age/300))+random(10), green(this.color), blue(this.color)*abs(sin(this.age/100))+random(10));
		if (this.age >= this.maxAge){
			this.reset(this.maxAge, 0);
		}
		this.x-=(sin(frameCount/50) * 2) - this.speed;
		if (this.x - this.r / 2 > windowWidth) {
			this.x = -this.r;
		}
		this.y+=cos(frameCount/50) * 2;
		this.age+=this.speed;
	}

	draw() {

		noStroke();
		let c1 = color(red(this.color), green(this.color), blue(this.color), this.alpha)
		fill(c1);
		circle(this.x, this.y, this.r);

		stroke(0, this.alpha);
		strokeWeight(map(this.r, 10, 250, 1, 7));
		noFill();
		let xOuter = this.x + random(-2, 2);
		let yOuter = this.y + random(-2, 2);
		//circle(xOuter, yOuter, this.r * abs(sin(this.age/100)));
	}
}

